<?php
/**
 * Dashboard-managed Ministries section.
 *
 * @package SurfsideTools
 */

if (!defined('ABSPATH')) { exit; }

function surfside_tools_ministries_render_cards($ministries, $title, $intro, $class = 'surfside-ministries') {
    if (empty($ministries)) return '';
    $heading_id = wp_unique_id('surfside-ministries-heading-'); ob_start(); ?>
    <section class="surfside-adult-ministries <?php echo esc_attr($class); ?>" aria-labelledby="<?php echo esc_attr($heading_id); ?>"><div class="surfside-adult-ministries__inner"><div class="surfside-adult-ministries__intro"><h2 id="<?php echo esc_attr($heading_id); ?>"><?php echo esc_html($title); ?></h2><?php if (trim((string)$intro) !== '') : ?><p><?php echo esc_html($intro); ?></p><?php endif; ?></div><div class="surfside-adult-ministries__grid surfside-staggered-cards">
    <?php foreach ($ministries as $ministry) : ?><article class="surfside-adult-ministries__card"><h3><?php if (!empty($ministry['icon'])) : ?><span aria-hidden="true"><?php echo esc_html($ministry['icon']); ?></span> <?php endif; ?><?php echo esc_html($ministry['name'] ?? ''); ?></h3><?php if(!empty($ministry['schedule'])): ?><p class="surfside-adult-ministries__schedule"><?php echo esc_html($ministry['schedule']); ?></p><?php endif; ?><?php if(!empty($ministry['location'])): ?><p class="surfside-adult-ministries__location"><?php echo esc_html($ministry['location']); ?></p><?php endif; ?><?php if(!empty($ministry['description'])): ?><p class="surfside-adult-ministries__description"><?php echo esc_html($ministry['description']); ?></p><?php endif; ?></article><?php endforeach; ?>
    </div></div></section><?php return ob_get_clean();
}

function surfside_tools_ministries_shortcode($attributes=array()) {
    $attributes=shortcode_atts(array('title'=>'Ministries','intro'=>'Find a place to connect, grow, serve, and build meaningful relationships throughout the week.'),$attributes,'surfside_ministries');
    $ministries=function_exists('surfside_tools_get_ministries')?surfside_tools_get_ministries():array();
    return surfside_tools_ministries_render_cards($ministries,$attributes['title'],$attributes['intro']);
}
add_shortcode('surfside_ministries','surfside_tools_ministries_shortcode');
function surfside_tools_adult_ministries_shortcode($attributes=array()){return surfside_tools_ministries_shortcode($attributes);} add_shortcode('surfside_adult_ministries','surfside_tools_adult_ministries_shortcode');

function surfside_tools_featured_ministries_shortcode($attributes=array()) {
    $attributes=shortcode_atts(array('title'=>'Ministries','intro'=>'Find a place to connect, grow, serve, and build meaningful relationships throughout the week.'),$attributes,'surfside_featured_ministries');
    $ministries=function_exists('surfside_tools_get_ministries')?surfside_tools_get_ministries():array();
    $featured=array_values(array_filter($ministries,function($m){return !empty($m['featured']);}));
    return surfside_tools_ministries_render_cards($featured,$attributes['title'],$attributes['intro'],'surfside-featured-ministries');
}
add_shortcode('surfside_featured_ministries','surfside_tools_featured_ministries_shortcode');

/** Compact directory with audience filtering and on-demand detail dialog. */
function surfside_tools_all_ministries_shortcode($attributes=array()) {
    $attributes=shortcode_atts(array('title'=>'Ministry Directory','intro'=>'Explore more ways to connect, grow, and serve at Surfside.'),$attributes,'surfside_all_ministries');
    $items=function_exists('surfside_tools_get_ministries')?array_values((array)surfside_tools_get_ministries()):array();
    if(empty($items)) return '';
    $choices=function_exists('surfside_tools_ministry_audience_choices')?surfside_tools_ministry_audience_choices():array('kids'=>'Kids','youth'=>'Youth','adults'=>'Adults','all_ages'=>'All Ages');
    $directory_id=wp_unique_id('surfside-ministry-directory-');
    $dialog_id=wp_unique_id('surfside-ministry-dialog-');
    ob_start(); ?>
    <section class="surfside-all-ministries" id="<?php echo esc_attr($directory_id); ?>"><div class="surfside-all-ministries__inner"><div class="surfside-all-ministries__intro"><h2><?php echo esc_html($attributes['title']); ?></h2><?php if(trim((string)$attributes['intro'])!==''): ?><p><?php echo esc_html($attributes['intro']); ?></p><?php endif; ?></div>
      <div class="surfside-all-ministries__filters" aria-label="Filter ministries by audience"><span>Filter by audience:</span><?php foreach($choices as $key=>$label): ?><button type="button" data-ministry-filter="<?php echo esc_attr($key); ?>" aria-pressed="false"><?php echo esc_html($label); ?></button><?php endforeach; ?><button type="button" class="surfside-all-ministries__clear" data-ministry-filter-clear hidden>Clear filter</button></div>
      <div class="surfside-all-ministries__list" data-ministry-directory-list>
      <?php foreach($items as $m): $audiences=isset($m['audiences'])&&is_array($m['audiences'])?$m['audiences']:array('adults'); $featured=!empty($m['featured']); ?>
        <button type="button" class="surfside-all-ministries__item" data-ministry-directory-item data-featured="<?php echo $featured?'1':'0'; ?>" data-audiences="<?php echo esc_attr(implode(' ',array_map('sanitize_key',$audiences))); ?>" data-name="<?php echo esc_attr($m['name']??''); ?>" data-icon="<?php echo esc_attr($m['icon']??''); ?>" data-schedule="<?php echo esc_attr($m['schedule']??''); ?>" data-location="<?php echo esc_attr($m['location']??''); ?>" data-description="<?php echo esc_attr($m['description']??''); ?>" aria-haspopup="dialog" aria-controls="<?php echo esc_attr($dialog_id); ?>" <?php if($featured): ?>hidden<?php endif; ?>><span class="surfside-all-ministries__name"><?php if(!empty($m['icon'])): ?><span aria-hidden="true"><?php echo esc_html($m['icon']); ?></span> <?php endif; ?><?php echo esc_html($m['name']??''); ?></span><span class="surfside-all-ministries__view">View details</span></button>
      <?php endforeach; ?>
      </div>
      <dialog class="surfside-ministry-dialog" id="<?php echo esc_attr($dialog_id); ?>" data-ministry-dialog aria-labelledby="<?php echo esc_attr($dialog_id); ?>-title"><div class="surfside-ministry-dialog__panel"><button type="button" class="surfside-ministry-dialog__close" data-ministry-dialog-close aria-label="Close ministry details">×</button><h3 id="<?php echo esc_attr($dialog_id); ?>-title" data-ministry-dialog-title></h3><p class="surfside-ministry-dialog__schedule" data-ministry-dialog-schedule hidden></p><p class="surfside-ministry-dialog__location" data-ministry-dialog-location hidden></p><p class="surfside-ministry-dialog__description" data-ministry-dialog-description hidden></p></div></dialog>
    </div><style>.surfside-all-ministries{margin:28px 0}.surfside-all-ministries__inner{max-width:1100px;margin:0 auto}.surfside-all-ministries__intro{margin-bottom:12px}.surfside-all-ministries__intro h2{margin:0 0 5px}.surfside-all-ministries__intro p{margin:0;color:#60708a}.surfside-all-ministries__filters{display:flex;align-items:center;flex-wrap:wrap;gap:7px;margin:0 0 14px;color:#60708a;font-size:.85rem}.surfside-all-ministries__filters>span{font-weight:700;color:#31566d}.surfside-all-ministries__filters button{padding:6px 10px;border:1px solid var(--surfside-color-border,#d8e1e9);border-radius:999px;background:#fff;color:#31566d;font:inherit;font-weight:800;cursor:pointer}.surfside-all-ministries__filters button[aria-pressed="true"]{border-color:var(--surfside-color-blue-700,#075c9c);background:#eef4f7;color:var(--surfside-color-blue-700,#075c9c)}.surfside-all-ministries__clear{border-color:transparent!important;background:transparent!important;text-decoration:underline}.surfside-all-ministries__list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.surfside-all-ministries__item{appearance:none;display:flex;min-height:74px;padding:10px 14px;border:1px solid var(--surfside-color-border,#d8e1e9);border-radius:10px;background:#fff;color:inherit;font:inherit;flex-direction:column;align-items:center;justify-content:center;gap:5px;text-align:center;cursor:pointer;transition:border-color .15s ease,box-shadow .15s ease,transform .15s ease}.surfside-all-ministries__item[hidden]{display:none!important}.surfside-all-ministries__item:hover{border-color:#a9bdca;box-shadow:0 4px 12px rgba(6,27,51,.07);transform:translateY(-1px)}.surfside-all-ministries__item:focus-visible{outline:3px solid rgba(11,95,165,.2);outline-offset:2px}.surfside-all-ministries__name{font-size:1rem;font-weight:800;line-height:1.2}.surfside-all-ministries__view{color:#60708a;font-size:.75rem;font-weight:700}.surfside-ministry-dialog{width:min(calc(100% - 2rem),34rem);padding:0;border:0;border-radius:18px;background:#fff;color:var(--surfside-color-ink,#10243a);box-shadow:0 24px 70px rgba(6,27,51,.28)}.surfside-ministry-dialog::backdrop{background:rgba(6,27,51,.52)}.surfside-ministry-dialog__panel{position:relative;padding:28px}.surfside-ministry-dialog__close{position:absolute;top:12px;right:14px;width:38px;height:38px;padding:0;border:0;border-radius:50%;background:#eef4f7;color:#31566d;font-size:1.6rem;line-height:1;cursor:pointer}.surfside-ministry-dialog h3{margin:0 44px 16px 0;color:var(--surfside-color-ocean-950,#061b33);font-size:1.55rem;line-height:1.2}.surfside-ministry-dialog__schedule{margin:0;color:var(--surfside-color-blue-700,#075c9c);font-weight:800}.surfside-ministry-dialog__location{margin:.25rem 0 0;color:#60708a}.surfside-ministry-dialog__description{margin:1rem 0 0;line-height:1.6}.surfside-ministry-dialog p[hidden]{display:none!important}@media(max-width:900px){.surfside-all-ministries__list{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:620px){.surfside-all-ministries__list{grid-template-columns:1fr}.surfside-all-ministries__item{min-height:64px}}</style>
    <script>(function(){var root=document.getElementById(<?php echo wp_json_encode($directory_id); ?>);if(!root)return;var items=root.querySelectorAll('[data-ministry-directory-item]'),buttons=root.querySelectorAll('[data-ministry-filter]'),clear=root.querySelector('[data-ministry-filter-clear]'),dialog=root.querySelector('[data-ministry-dialog]'),title=root.querySelector('[data-ministry-dialog-title]'),schedule=root.querySelector('[data-ministry-dialog-schedule]'),location=root.querySelector('[data-ministry-dialog-location]'),description=root.querySelector('[data-ministry-dialog-description]'),close=root.querySelector('[data-ministry-dialog-close]');function reset(){items.forEach(function(item){item.hidden=item.getAttribute('data-featured')==='1';});buttons.forEach(function(button){button.setAttribute('aria-pressed','false');});if(clear)clear.hidden=true;}function fill(node,value){if(!node)return;node.textContent=value||'';node.hidden=!value;}function openDetails(item){if(!dialog)return;var name=item.getAttribute('data-name')||'',icon=item.getAttribute('data-icon')||'';if(title)title.textContent=(icon?icon+' ':'')+name;fill(schedule,item.getAttribute('data-schedule')||'');fill(location,item.getAttribute('data-location')||'');fill(description,item.getAttribute('data-description')||'');if(typeof dialog.showModal==='function')dialog.showModal();else dialog.setAttribute('open','open');}buttons.forEach(function(button){button.addEventListener('click',function(){var filter=button.getAttribute('data-ministry-filter');buttons.forEach(function(other){other.setAttribute('aria-pressed',other===button?'true':'false');});items.forEach(function(item){var audiences=(item.getAttribute('data-audiences')||'').split(/\s+/);item.hidden=audiences.indexOf(filter)===-1;});if(clear)clear.hidden=false;});});items.forEach(function(item){item.addEventListener('click',function(){openDetails(item);});});if(clear)clear.addEventListener('click',reset);if(close)close.addEventListener('click',function(){if(typeof dialog.close==='function')dialog.close();else dialog.removeAttribute('open');});if(dialog)dialog.addEventListener('click',function(event){if(event.target===dialog&&typeof dialog.close==='function')dialog.close();});reset();}());</script></section>
    <?php return ob_get_clean();
}
add_shortcode('surfside_all_ministries','surfside_tools_all_ministries_shortcode');
